import{z as p,x as i,o as r,c as B,q as A,j as l,D as e,d as s,s as o,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"P4 可编程","description":"","frontmatter":{"title":"P4 可编程","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/p4-programmable.md","filePath":"cs/p4-programmable.md","lastUpdated":1791413859000}'),P={name:"cs/p4-programmable.md"};function d(C,a,m,h,c,u){const t=i("Mermaid");return r(),B("div",null,[a[2]||(a[2]=A('<h1 id="p4-可编程" tabindex="-1">P4 可编程 <a class="header-anchor" href="#p4-可编程" aria-label="Permalink to &quot;P4 可编程&quot;">​</a></h1><div class="epigraph"><p>P4 描述解析器与匹配-动作流水线，编译到 ASIC 或 CPU；协议头不再焊死在硅里，但仍受阶段数与 TCAM 形状约束。</p><footer>—— 据 Bosshart et al., P4, ACM SIGCOMM CCR 2014；P4<sub>16</sub> 语言规范整理</footer></div><p><a href="/cs/sdn-openflow">上一课</a> 的匹配域是固定的。新隧道头要等芯片代次。缺口是<strong>可编程数据面</strong>：P4 写 parse → match-action → deparse。本课不把 Clos 拓扑写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>OpenFlow 加字段靠规范版本。P4：声明头、解析图、表、动作，目标无关再映射到 Tofino 或智能网卡。仍不是通用 CPU：无任意循环、表宽与阶段固定。INT 带内遥测、自定义熵、新封装可在此做。控制面仍要某协议装表——P4 不替代 BGP，只替换「转发 ASIC 焊死」那一层。</p><p>不要把 P4 写成智能合约或机器学习训练。</p><p><span class="marginnote">P4<sub>16</sub>。PSA/PNA 架构。本课不写完整编译器。</span></p><h3 id="不是通用-cpu" tabindex="-1">不是通用 CPU <a class="header-anchor" href="#不是通用-cpu" aria-label="Permalink to &quot;不是通用 CPU&quot;">​</a></h3><p>解析与表可描述，阶段数与表宽仍硬。不取消 BGP，只放开头格式。错误程序可成黑洞。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：解析图 → 多级表 → 出端口。对照 TCAM：表仍可能编译成 TCAM/SRAM。与线路码对照：都是「可描述的转发」，一层在 PHY，一层在 L2–L4。</p>',11)),(r(),l(n,null,{default:e(()=>[o(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PAR%5B%22%E5%8F%AF%E7%BC%96%E7%A8%8B%E8%A7%A3%E6%9E%90%22%5D%20--%3E%20MA%5B%22%E5%8C%B9%E9%85%8D-%E5%8A%A8%E4%BD%9C%E9%98%B6%E6%AE%B5%22%5D%0A%20%20MA%20--%3E%20DEP%5B%22%E9%87%8D%E7%BB%84%22%5D%0A%20%20CTL%5B%22%E6%8E%A7%E5%88%B6%E9%9D%A2%22%5D%20--%3E%20MA%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[s("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"VXLAN/SR 新 SID 可用 P4 先部署再等标准芯片。错误程序可把交换机变成黑洞，需要测试与资源上限。C10K 后课是主机端；这里是网络端可编程。容量 \\(C\\) 仍由端口 PHY 决定，P4 只动如何选口。",-1)),a[5]||(a[5]=E("p",null,"把一个隧道包放进流水线走一遍，可编程与固定的差别就看见了：解析图换成认 VXLAN 头只需要改程序描述，表与动作按新头编排，硬件还是那几级阶段。",-1)),(r(),l(n,null,{default:e(()=>[o(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20PKT%5B%22%E8%BF%9B%E5%8C%85%EF%BC%9A%E5%A4%96%E5%B1%82%E4%BB%A5%E5%A4%AA%E7%BD%91%E5%B8%A7%22%5D%20--%3E%20P1%5B%22%E8%A7%A3%E6%9E%90%E5%9B%BE%E9%80%90%E5%A4%B4%E8%AE%A4%EF%BC%9AEth%20%E2%86%92%20IP%20%E2%86%92%20UDP%20%E2%86%92%20VXLAN%22%5D%0A%20%20P1%20--%3E%20T1%5B%22%E8%A1%A8%201%EF%BC%9A%E6%8C%89%E5%A4%96%E5%B1%82%E7%9B%AE%E7%9A%84%20IP%20%E6%9F%A5%E9%9A%A7%E9%81%93%E7%BB%88%E7%82%B9%22%5D%0A%20%20T1%20--%3E%20T2%5B%22%E8%A1%A8%202%EF%BC%9A%E5%8C%B9%E9%85%8D%20VNI%EF%BC%8C%E5%AE%9A%E4%BD%8D%E5%86%85%E5%B1%82%E4%B8%BB%E6%9C%BA%22%5D%0A%20%20T2%20--%3E%20ACT%5B%22%E5%8A%A8%E4%BD%9C%EF%BC%9A%E5%89%A5%E5%A4%96%E5%B1%82%E5%A4%B4%EF%BC%8CTTL%20%E5%87%8F%E4%B8%80%22%5D%0A%20%20ACT%20--%3E%20DEP%5B%22deparse%20%E6%8C%89%E8%A7%A3%E6%9E%90%E5%9B%BE%E9%87%8D%E7%BB%84%E5%B8%A7%22%5D%0A%20%20DEP%20--%3E%20OUT%5B%22%E6%9F%A5%E8%BD%AC%E5%8F%91%E8%A1%A8%EF%BC%8C%E9%80%89%E5%87%BA%E5%8F%A3%E5%8F%91%E5%87%BA%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=A('<p><span class="marginnote">直觉类比：固定 ASIC 像只卖固定菜单的厨房，P4 是把菜谱（解析图加表加动作）交给同一个厨房——灶眼数量（阶段数）与货架宽度（表大小）仍然焊死，能换的只是做什么菜。</span></p><p><span class="marginnote">常见误区：初学者容易以为 P4 让交换机变成通用服务器。它没有任意循环、表宽与阶段数固定、每包预算按纳秒算——能在流水线几跳内表达的转发逻辑才是 P4 的疆域，更复杂的就交给主机端 CPU。</span></p><p><span class="marginnote">为什么重要：P4 程序写错往往不是报错而是黑洞——错误表项让匹配不上的包无声消失；所以可编程数据面上线必须配测试与资源上限，这套功夫与控制面协议的容错是两码事。</span></p><p>与 HOL：流水线阶段加深可能加纳秒，不解决输出热点。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 eBPF 与 P4 的全部对照。数据中心 Clos 是下一课。后课默认：数据面可编程受流水线资源约束，不是通用计算。</p><p>把全部政策塞进 P4 会让控制面版本与芯片资源强耦合。</p><p>下一课<a href="/cs/datacenter-clos">数据中心 Clos / 胖树</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>P4 定义解析与表，编译到受限硬件。</li><li>不取消控制面协议，只放开头格式。</li><li>资源阶段数是硬边界。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：Bosshart et al., 2014；P4<sub>16</sub>。</li></ul>',10))])}const b=p(P,[["render",d]]);export{T as __pageData,b as default};
